corrected_code:
const { Queue } = require('bullmq');
const inferenceQueue = new Queue('radiology-ai-inference', { connection: redisClient });

app.get('/api/radiology/scans/inference/:jobId', authGuard, async (req, res) => {
  const job = await inferenceQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).send('Job not found');
  const assignment = await PatientPhysicianAssignment.findOne({
    where: { patientId: job.data.patientId, doctorId: req.user.id }
  });
  if (!assignment && req.user.patientId !== job.data.patientId) {
    return res.status(403).send('Forbidden: unauthorized access to patient diagnostic findings');
  }
  if (!job.returnvalue) return res.status(202).send('Inference in progress');
  res.json({
    scanId: job.data.scanId,
    patientId: job.data.patientId,
    findings: job.returnvalue.pathologyFindings,
    confidenceScore: job.returnvalue.malignancyScore
  });
});
